bool isTrackInViewport(String path) {
  if (!isMounted()) return false;
  final rowContext = rowKeys[path]?.currentContext;
  if (rowContext == null) return false;
  final rowBox = rowContext.findRenderObject();
  if (rowBox is! RenderBox || !rowBox.hasSize) return false;

  // We use the ListView/ScrollView render box as the viewport.
  final viewportContext = scroll.hasClients ? scroll.context : null;
  if (viewportContext == null) return false;
  final viewportBox = viewportContext.findRenderObject();
  if (viewportBox is! RenderBox || !viewportBox.hasSize) return false;

  // Intersects when its vertical span overlaps the viewport vertical span.
  final rowTop = rowBox.localToGlobal(Offset.zero, ancestor: viewportBox).dy;
  final rowBottom = rowBox
      .localToGlobal(rowBox.size.bottomRight(Offset.zero), ancestor: viewportBox)
      .dy;
  return rowBottom > 0 && rowTop < viewportBox.size.height;
}

